import { gql } from "@apollo/client";
import { CORE_MESSAGE_FIELDS } from "./fragments";

export const SIGNUP = gql`
	mutation Signup($input: SignupInput!) {
		signup(input: $input) {
			completed
			key
			message
		}
	}
`;

export const SIGNIN = gql`
	mutation Signin($signinId: String!, $password: String!) {
		signin(id: $signinId, password: $password)
	}
`;

export const SIGNOUT = gql`
	mutation Signout {
		signout
	}
`;

export const SET_USER_CONFIG = gql`
	mutation SetUserConfig($input: SetUserConfigInput!) {
		setUserConfig(input: $input) {
			config {
				videoAutoPlay
			}
		}
	}
`;

export const CHANGE_PASSWORD = gql`
	mutation ChangePassword($input: ChangePasswordInput!) {
		changePassword(input: $input) {
			success
		}
	}
`;

export const ME = gql`
	query Me {
		me {
			id
			name
			config {
				videoAutoPlay
			}
		}
	}
`;

export const BUILTIN_WEBLINKS = gql`
	query BuiltinWeblinks($input: BuiltinWeblinksInput) {
		builtinWeblinks(input: $input) {
			hidedIds
			weblinks {
				name
				url
				color
				backgroundColor
				id
			}
		}
	}
`;

export const TOGGLE_BUILTIN_WEBLINK = gql`
	mutation ToggleBuiltinWeblink($weblinkId: Int!) {
		toggleBuiltinWeblink(weblinkId: $weblinkId)
	}
`;

export const OWN_WEBLINKS = gql`
	query OwnWeblinks {
		ownWeblinks {
			name
			url
			color
			backgroundColor
			id
			groupId
		}
	}
`;

export const MY_WEBLINK_GROUPS = gql`
	query MyWeblinkGroups {
		myWeblinkGroups {
			id
			name
			seq
			weblinks {
				name
				url
				color
				backgroundColor
				id
				groupId
			}
		}
	}
`;

export const ADD_WEBLINK = gql`
	mutation Mutation($input: AddWeblinkInput!) {
		addWeblink(input: $input) {
			weblink {
				name
				url
				color
				backgroundColor
				id
				groupId
			}
		}
	}
`;

export const UPDATE_WEBLINK = gql`
	mutation UpdateWeblink($input: UpdateWeblinkInput!) {
		updateWeblink(input: $input) {
			weblink {
				name
				url
				color
				backgroundColor
				id
				groupId
			}
		}
	}
`;

export const DELETE_WEBLINK = gql`
	mutation DeleteWeblink($weblinkId: Int!) {
		deleteWeblink(weblinkId: $weblinkId)
	}
`;

export const REORDER_WEBLINKS = gql`
	mutation ReorderWeblinks($weblinkIds: [Int!]!) {
		reorderWeblinks(weblinkIds: $weblinkIds)
	}
`;

export const SET_WEBLINK_GROUP = gql`
	mutation SetWeblinkGroup($weblinkId: Int!, $groupId: Int) {
		setWeblinkGroup(weblinkId: $weblinkId, groupId: $groupId)
	}
`;

export const CREATE_WEBLINK_GROUP = gql`
	mutation CreateWeblinkGroup($name: String!) {
		createWeblinkGroup(name: $name) {
			id
			name
			seq
		}
	}
`;

export const UPDATE_WEBLINK_GROUP = gql`
	mutation UpdateWeblinkGroup($id: Int!, $name: String!) {
		updateWeblinkGroup(id: $id, name: $name) {
			id
			name
			seq
		}
	}
`;

export const DELETE_WEBLINK_GROUP = gql`
	mutation DeleteWeblinkGroup($groupId: Int!) {
		deleteWeblinkGroup(groupId: $groupId)
	}
`;

export const REORDER_WEBLINK_GROUPS = gql`
	mutation ReorderWeblinkGroups($groupIds: [Int!]!) {
		reorderWeblinkGroups(groupIds: $groupIds)
	}
`;

export const MESSAGEBOARD = gql`
	${CORE_MESSAGE_FIELDS}
	query Messageboard($page: Int!) {
		messageboard(page: $page) {
			messages {
				...CoreMessageFields
				reply {
					...CoreMessageFields
				}
				likes {
					userId
				}
			}
			totalCount
		}
	}
`;

export const LIKE_MESSAGE = gql`
	mutation LikeMessage($input: LikeMessageInput!) {
		likeMessage(input: $input) {
			message {
				id
				type
				likes {
					userId
				}
			}
		}
	}
`;

export const UNLIKE_MESSAGE = gql`
	mutation UnlikeMessage($input: UnlikeMessageInput!) {
		unlikeMessage(input: $input) {
			message {
				id
				type
				likes {
					userId
				}
			}
		}
	}
`;

export const POST_MESSAGE = gql`
	mutation PostMessage($input: PostMessageInput!) {
		postMessage(input: $input) {
			completed
		}
	}
`;

export const DELETE_MESSAGE = gql`
	mutation DeleteMessage($input: DeleteMessageInput!) {
		deleteMessage(input: $input) {
			success
		}
	}
`;

export const FILES = gql`
	query Files {
		files {
			url
			date
			size
		}
	}
`;

export const MY_VIDEO_ITEMS = gql`
	query MyVideoItems {
		myVideoItems {
			id
			video {
				id
				title
				length
			}
			playlists {
				id
				name
				videoCount
			}
		}
	}
`;

export const MY_PLAYLISTS = gql`
	query MyPlaylists {
		myPlaylists {
			id
			name
			videoCount
			shareCode
		}
	}
`;

export const ADD_VIDEO_ITEM = gql`
	mutation AddVideoItem($input: AddVideoItemInput!) {
		addVideoItem(input: $input) {
			video {
				id
				length
				title
			}
		}
	}
`;

export const DELETE_VIDEO_ITEM = gql`
	mutation DeleteVideoItem($itemId: Int!) {
		deleteVideoItem(itemId: $itemId)
	}
`;

export const CREATE_PLAYLIST = gql`
	mutation CreatePlaylist($name: String!) {
		createPlaylist(name: $name) {
			id
			name
			videoCount
			shareCode
		}
	}
`;

export const UPDATE_PLAYLIST = gql`
	mutation UpdatePlaylist($id: Int!, $name: String!) {
		updatePlaylist(id: $id, name: $name) {
			id
			name
			videoCount
			shareCode
		}
	}
`;

export const DELETE_PLAYLIST = gql`
	mutation DeletePlaylist($id: Int!) {
		deletePlaylist(id: $id)
	}
`;

export const SET_VIDEO_PLAYLISTS = gql`
	mutation SetVideoPlaylists($queueItemId: Int!, $playlistIds: [Int!]!) {
		setVideoPlaylists(queueItemId: $queueItemId, playlistIds: $playlistIds) {
			id
			name
			videoCount
		}
	}
`;

export const IMPORT_PLAYLIST = gql`
	mutation ImportPlaylist($shareCode: String!, $name: String) {
		importPlaylist(shareCode: $shareCode, name: $name) {
			id
			name
			videoCount
			shareCode
		}
	}
`;

export const QUERIES_AFFECTED_BY_SIGN = [
	{ query: ME },
	{ query: FILES },
	{ query: OWN_WEBLINKS },
	{ query: BUILTIN_WEBLINKS },
	{ query: MY_WEBLINK_GROUPS },
	{ query: MY_VIDEO_ITEMS },
	{ query: MY_PLAYLISTS },
];
